UPDATE courses SET
    course_description = '<h4>Overview</h4><p>Become a professional builder or construction manager in the low-rise sector with this Certificate IV from TAFE SA. This nationally recognised qualification is a core requirement, along with trade experience, for getting your South Australian Building Work Supervisor Registration. The builder is the person at the heart of a build and takes responsibility for all aspects of the job from planning to ensuring a successful outcome. The course covers finances, planning and estimating, contracts and schedules, legal requirements, OHS compliance, structural principles, and key aspects of managing a small business. Building Work Supervisors make sure that all building work performed meets the required building standards. Supervisors must be registered and approved by Consumer and Business Services (CBS).</p>',
    course_duration_per_week = 78,
    offshore_tuition_fee = 21360,
    onshore_tuition_fee = NULL,
