    updated_at = NOW()
WHERE cricos_course_code = '104666D';

UPDATE courses SET
    course_description = '<h4>Overview</h4><p>If you would you like to work in the building and construction industry as a Site Supervisor or Site Manager, this is the course for you. Covering all the essential elements of communication, teamwork, problem solving, initiative and enterprise, planning and organisation, self-management, continuous learning, and the use of technology, tools and equipment, this comprehensive course will have you job ready and eager to build your future career. You will gain the knowledge you need to apply for your SA Building Work Supervisor Registration, provided you have the necessary experience as required by Consumer and Business Services (CBS).</p>',
