UPDATE courses SET
    course_description = '<h4>Overview</h4><p>Secure a bright future with an Associate Degree in Electrical Engineering from TAFE SA. This course was designed in response to the workforce needs of the electrical industry, one of South Australia’s major employers with opportunities in a range of industries including electricity generation and distribution, production line processing, and mining. You may be involved in overseeing the condition of electrical equipment, the maintenance and commissioning of electrical equipment, or working alongside engineers to design and prototype advanced electrical technology. Be part of this exciting growth industry with your Associate Degree.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 41520,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = 2500,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Satisfactory completion of Year 12 including Year 12 Maths, or overseas equivalent or the successful completion of the CIII in Engineering – Technical (if no Year 12 maths) or the Diploma of Engineering – Technical (if no Year 12 background).</li><li>All international students will be required to undertake an Engineering Diagnostic Test during the orientation and induction program at TAFE SA (prior to commencing their course) to demonstrate sufficient and required technical skills for academic success. See course note for more information.</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>Academic <a href="https://www.tafesa.edu.au/international/entry-requirements">IELTS score</a> of 6.0 Overall with a minimum of 5.5 in all bands or equivalent.</li></ul></td></tr></tbody></table>',
    apply_form = 'https://www.tafesa.edu.au/xml/course/in/in_2022AC00079.aspx',
    updated_at = NOW()
WHERE cricos_course_code = '092137K';

UPDATE courses SET
    course_description = '<h4>Overview</h4><p>Step Into the Spotlight of Strategic Marketing. Ready to take your marketing skills to the next level? The Diploma of Marketing and Communication [BSB50620] is your launchpad into high-impact roles where creativity and strategy come together. This nationally recognised qualification is ideal for those who want marketing and communication skills that can be applied across all organisations and industries—and are ready to shape campaigns and contribute to organisational growth across both digital and traditional platforms. What You’ll Learn • Apply strategic marketing planning that deliver measurable results • Manage marketing projects and promotions with confidence • Analyse market trends and consumer behaviour to identify opportunities • Create persuasive content for websites, email campaigns, and social media • Master digital marketing, AI tools and communication platforms The Diploma of Marketing and Communication equips you with practical, industry-ready skills to achieve meaningful results and move your career forward. This course incorporates the Diploma of Marketing and Communication plus the 6 entry units required for the qualification.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 15760,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Satisfactory completion of <a href="https://www.tafesa.edu.au/international/entry-requirements">Year 12 or overseas equivalent</a> .</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>Academic <a href="https://www.tafesa.edu.au/international/entry-requirements">IELTS score</a> of 6.0 Overall with minimum of 5.0 in all bands or equivalent.</li></ul></td></tr></tbody></table>',
