UPDATE courses SET
    course_description = '<h4>Overview</h4><p>This course is designed for students with intermediate level -English language skills (equivalent to IELTS 4.5-5.0) who are planning to do further study at TAFE SA or university, or those who simply wish to further their English language and academic skills (English only) The expert tuition by our highly trained and experienced teachers will help you to gain the skills needed to reach your goals in the Australian academic environment, including: - Speaking, listening, reading and writing for academic and vocational contexts - Academic study skills, including group work, formal speaking and time management - Effective communication skills - Orientation to tertiary study in Australia</p>',
    course_duration_per_week = 26,
    offshore_tuition_fee = 8040,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>English Proficiency</strong></td><td><ul><li>A general or academic <a href="https://www.tafesa.edu.au/international/entry-requirements">IELTS score</a> of 4.5 with a minimum of 4.5 in all bands or equivalent. Any student wishing to enter an award course which requires 6.0 IELTS or equivalent entry will need to enter EAP 20 with 5.0 IELTS in all bands.Onshore students can sit a pre-entry test at the English Language Centre. In order to receive the EAP completion certificate and recommendation for a future course, students must undertake a minimum of 10 weeks of study (weeks 11-20).</li></ul></td></tr></tbody></table>',
    apply_form = 'https://www.tafesa.edu.au/xml/course/in/in_2022BR00003.aspx',
    updated_at = NOW()
WHERE cricos_course_code = '064266M';

UPDATE courses SET
    course_description = '<h4>Overview</h4><p>This course is aimed at students who need advanced English skills to study at TAFE SA or university -(undergraduate or postgraduate level). Or those wishing to increase their English language and academic skills to an advanced level (English only). This course is delivered by highly trained and experienced teachers and focuses on: - Speaking, listening, reading and writing for tertiary contexts - Academic study skills - Orientation to tertiary study in Australia - Delivery in a simulated tertiary environment (content and assessment) Exploring language required for students’ academic or professional pathway</p>',
