UPDATE courses SET
    course_description = '<h4>Overview</h4><p>Gain the essential knowledge and skills required to provide caring, compassionate and effective nursing care as an Enrolled Nurse working under the supervision of a Registered Nurse. This course focuses on integrating theory with practice, giving you the skills to problem solve and work in a collaborative team environment across a range of health care settings.</p>',
    course_duration_per_week = 92,
    offshore_tuition_fee = 36960,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = 1500,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Ability to meet the physical demands of nursing work, particularly the requirements of manual handling.</li><li>Satisfactory completion of <a href="https://www.tafesa.edu.au/international/entry-requirements">Year 12 or overseas equivalent</a> .</li><li>All international students will be required to undertake a Maths test during the orientation and induction program at TAFE SA (prior to commencing their Diploma) to demonstrate sufficient numeracy (maths) skills. This is a requirement of the Australian Nursing and Midwifery Accreditation Council.</li><li>Should the student fail this test, they will be required to undertake the TAFE SA Maths for Nursing short course. This Maths short course is taught online and concurrently during the 1st semester of the Diploma of Nursing. The cost of this unit is $A200.</li><li>International students who fail the Maths for Nursing short course will need to either defer their Diploma of Nursing enrolment until the successful completion of the short course (or an alternative maths unit) or cancel their Diploma of Nursing enrolment. Failure of successfully completing this maths short course (or any maths unit) will mean the student has not satisfied the numeracy requirement.</li><li>International students must be 18 years old at the start of study.</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>An academic <a href="https://www.tafesa.edu.au/international/entry-requirements">IELTS score</a> of 7.0 overall with minimum of 7.0 in Listening, Speaking and Reading and 6.5 in Writing or equivalent or PTE Academic score of 63 with minimum of 58 in Listening, 76 Speaking and 59 in Reading and 60 in writing as required by the Nursing and Midwifery Board of Australia (Ahpra). This test result must be less than 12 months old from the date of commencement of the Diploma of Nursing. For more details please refer to https://www.ahpra.gov.au/Registration/Registration-Standards/English-language-skills/English-language-skills-registration-standard.aspx</li></ul></td></tr></tbody></table>',
    apply_form = 'https://www.tafesa.edu.au/xml/course/in/in_2026TP01261.aspx',
    updated_at = NOW()
WHERE cricos_course_code = '111783G';

UPDATE courses SET
    course_description = '<h4>Overview</h4><p>The Advanced Diploma of Oral Health (Dental Hygiene) is designed to provide learners with the skills and knowledge on graduation to apply to the Australian Health Practitioner Regulation Agency (AHPRA) to work as a dental hygienist in both private and government sectors in accordance with the legislative provisions and contemporary dental hygiene practice and theory.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 72440,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = 10000,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Satisfactory completion of <a href="https://www.tafesa.edu.au/international/entry-requirements">Year 12 or overseas equivalent</a> .</li><li>Successful completion of the TAFE SA Dental Hygiene Admission Test. To be successful in this test applicants would need a Certificate III in Dental Assisting or recent dental experience. The test is only conducted between Adelaide office hours of 9.00am-5.00pm Monday-Friday in October of each year for overseas based candidates (via an online system) or November of each year for onshore candidates. Please contact the TAFE SA International Unit for dates. A $A440 test administration fee applies. See below course notes section for further details.</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>Academic <a href="https://www.tafesa.edu.au/international/entry-requirements">IELTS score</a> of 7.0 Overall with a minimum of 7.0 in all bands, the Occupational English Test – minimum of B''s in all areas of assessment, or equivalent.</li></ul></td></tr></tbody></table>',
