UPDATE courses SET
    course_description = '<h4>Overview</h4><p>Do you love travel and want to work in a dynamic, fast-paced environment? The exciting world of travel and tourism is for you. Gain the skills you need to work in a travel agency, a tour operator, a tourism authority, a cruise company or airline, or a visitor information centre. From wineries and art galleries to local and international travel, you’ll graduate ready to work. Learn about customer service, tour operations, managing a team in the workplace, budgets and finance, and sales and marketing. The Diploma of Travel and Tourism Management is your ticket to success.</p>',
    course_duration_per_week = 52,
