UPDATE courses SET
    course_description = '<h4>Overview</h4><p>This qualification reflects the role of individuals who perform advanced diagnostic tasks in the automotive retail, service and repair industry. It is designed for technicians who have completed a Certificate III in an automotive trade and wish to gain higher-level skills in the advanced diagnosis of complex vehicle systems. The course combines practical and theoretical learning, covering automotive electrical systems, engine management and vehicle safety systems. Graduates will be prepared for a variety of employment opportunities in the diagnostic field, including progression into leadership roles such as workshop foreperson or leading hand.</p>',
    course_duration_per_week = 26,
    offshore_tuition_fee = 9070,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = 1000,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Satisfactory completion of the Certificate III in Light Vehicle Mechanical Technology or equivalent</li><li>Indian, Pakistani, Sri Lankan, Bangladeshi and Nepalese students need satisfactory completion of <a href="https://www.tafesa.edu.au/international/entry-requirements">Year 12 or overseas equivalent</a> 60% in the top 4 subjects (excluding native language). If student has needed to re-sit for their exam, student will also need to provide all exam results.</li><li>Ability to meet the physical demands of working in the automotive industry, particularly the requirements of manual handing.</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>Academic <a href="https://www.tafesa.edu.au/international/entry-requirements">IELTS score</a> of 6.0 Overall with minimum of 5.0 in all bands or equivalent.</li></ul></td></tr></tbody></table>',
    apply_form = 'https://www.tafesa.edu.au/xml/course/in/in_2026TP00975.aspx',
    updated_at = NOW()
WHERE cricos_course_code = '091649E';

UPDATE courses SET
    course_description = '<h4>Overview</h4><p>This qualification reflects the role of individuals who diagnose, analyse, evaluate, design and modify vehicle systems in the automotive retail, service and repair industry. Students will develop advanced technical skills while also learning how to document specifications and procedures. The course equips mechanics who want to be at the cutting edge of automotive technologies with coverage of areas such as estimating and quoting the cost of repairs. Graduates will be well-prepared for employment in modern mechanical workshops and for taking on higher-level responsibilities within the industry.</p>',
