UPDATE courses SET
    course_description = '<h4>Overview</h4><p>Learn the skills you need to work in engineering design with this Diploma. Become a CAD draftsperson, maintenance and service technician, civil, mechanical or mechatronics technician, or engineering technologist. Pursue your career in a diverse range of fields including design consultancies, the high-tech defence industry, in manufacturing, local and state government, oil and gas, transport, and construction services organisations. Your study at TAFE SA has a focus on translating complex theoretical concepts into real world engineering applications. Learn how to solve engineering problems and find the best solutions for the job. Completion of this Diploma can lead to further study in an Associate Degree in Engineering at TAFE SA and onto university. This is a common and recommended pathway for students, and we can help you explore these options.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 20470,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
