UPDATE courses SET
    course_description = '<h4>Overview</h4><p>Find your future in South Australia’s booming electronics industry. Designed in close collaboration with the industry, this course gives you maximum employability. Become a technical officer in the electronics industry and related areas like defence, mining, biomedical, and communications. You can work alongside engineers on the design and prototyping of advanced technology, or customising computer-controlled video equipment in a television studio. And you have the option to fast-track to a university degree. Learn about engineering practice, mathematics, digital electronics, analogue electronics, computer science, communication systems, project management and microcontroller programming as you study in small classes with an emphasis on practical and employability skills. Work-integrated learning means you enjoy a blend of lectures and practical laboratory and workshop sessions, including simulation tools. Study at TAFE SA for the career you want.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 41520,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = 2500,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Satisfactory completion of Year 12 including Year 12 Maths, or overseas equivalent or the successful completion of the CIII in Engineering – Technical (if no Year 12) or the Diploma of Engineering – Technical (if no Year 12 maths background).</li><li>All international students will be required to undertake an Engineering Diagnostic Test during the orientation and induction program at TAFE SA (prior to commencing their course) to demonstrate sufficient and required technical skills for academic success. See course note for more information.</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>Academic <a href="https://www.tafesa.edu.au/international/entry-requirements">IELTS score</a> of 6.0 Overall with a minimum of 5.5 in all bands or equivalent.</li></ul></td></tr></tbody></table>',
    apply_form = 'https://www.tafesa.edu.au/xml/course/in/in_2026AC00058.aspx',
    updated_at = NOW()
WHERE cricos_course_code = '066407J';

UPDATE courses SET
    course_description = '<h4>Overview</h4><p>Become a paraprofessional biomedical engineer and you could be installing, commissioning, testing and fault-finding essential biomedical equipment used in the health system. You will also be qualified for work in electronics and related industries, government, biomedical equipment, and research institutions. Learn about engineering practice, mathematics, digital electronics, anatomy and physiology for biomedical technologists, computer science, project management, biomedical instrumentation and microcontroller programming. And you have the option to fast-track to a university degree. Kick-start your career and further your studies in this rapidly growing sector with TAFE SA.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 41520,
    onshore_tuition_fee = NULL,
